import { Link } from "react-router-dom";
import { ScanLine, ArrowRight } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";

const Dashboard = () => {
  return (
    <div className="space-y-8">
      <div>
        <h2 className="text-[28px] font-bold text-foreground">Welcome back!</h2>
        <p className="mt-1 text-muted-foreground">Ready to optimize your conversions?</p>
      </div>

      <Card className="border-dashed border-2 border-primary/20 bg-primary/5">
        <CardContent className="flex flex-col items-center justify-center py-16 text-center">
          <div className="mb-4 flex h-14 w-14 items-center justify-center rounded-xl bg-primary/10">
            <ScanLine className="h-7 w-7 text-primary" />
          </div>
          <h3 className="text-xl font-semibold text-foreground">Start your first CRO audit</h3>
          <p className="mt-2 max-w-md text-sm text-muted-foreground">
            Enter any URL and CROBOT will analyze your page for conversion rate optimization opportunities using AI.
          </p>
          <Button asChild className="mt-6 rounded-lg px-6 py-2.5">
            <Link to="/scan">
              Start New Scan
              <ArrowRight className="ml-2 h-4 w-4" />
            </Link>
          </Button>
        </CardContent>
      </Card>
    </div>
  );
};

export default Dashboard;

import { useLocation, Link } from "react-router-dom";
import { LayoutDashboard, ScanLine, FileText, Puzzle, Settings, Zap, Bot } from "lucide-react";
import { NavLink } from "@/components/NavLink";
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarFooter,
  SidebarHeader,
  useSidebar,
} from "@/components/ui/sidebar";
import { Separator } from "@/components/ui/separator";

const navItems = [
  { title: "Dashboard", url: "/dashboard", icon: LayoutDashboard },
  { title: "New Scan", url: "/scan", icon: ScanLine, highlight: true },
  { title: "My Reports", url: "/reports", icon: FileText },
  { title: "Integrations", url: "/integrations", icon: Puzzle },
  { title: "Settings", url: "/settings", icon: Settings },
];

export function AppSidebar() {
  const { state } = useSidebar();
  const collapsed = state === "collapsed";
  const location = useLocation();

  const isActive = (path: string) => location.pathname === path || location.pathname.startsWith(path + "/");

  return (
    <Sidebar collapsible="icon" className="border-r-0">
      <SidebarHeader className="p-4">
        <Link to="/dashboard" className="flex items-center gap-2.5">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary">
            <Bot className="h-4.5 w-4.5 text-primary-foreground" />
          </div>
          {!collapsed && (
            <span className="text-lg font-bold tracking-tight text-sidebar-primary-foreground">
              CROBOT
            </span>
          )}
        </Link>
      </SidebarHeader>

      <SidebarContent className="px-2">
        <SidebarGroup>
          <SidebarGroupContent>
            <SidebarMenu>
              {navItems.map((item) => {
                const active = isActive(item.url);
                return (
                  <SidebarMenuItem key={item.title}>
                    <SidebarMenuButton
                      asChild
                      className={
                        active
                          ? "bg-primary/20 text-white border-l-2 border-primary rounded-none rounded-r-md"
                          : item.highlight
                          ? "text-sidebar-foreground hover:bg-primary/10 hover:text-white"
                          : "text-sidebar-foreground hover:bg-white/5 hover:text-white"
                      }
                    >
                      <NavLink to={item.url} activeClassName="">
                        <item.icon className="h-4 w-4" />
                        {!collapsed && <span>{item.title}</span>}
                      </NavLink>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                );
              })}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>

      <SidebarFooter className="p-3">
        <Separator className="mb-3 bg-sidebar-border" />
        {!collapsed ? (
          <Link
            to="/pricing"
            className="flex items-center justify-center gap-2 rounded-lg bg-gradient-to-r from-primary to-primary/80 px-4 py-2.5 text-sm font-medium text-primary-foreground transition-opacity hover:opacity-90"
          >
            <Zap className="h-4 w-4" />
            Upgrade to Pro
          </Link>
        ) : (
          <Link
            to="/pricing"
            className="flex items-center justify-center rounded-lg bg-primary p-2 text-primary-foreground transition-opacity hover:opacity-90"
          >
            <Zap className="h-4 w-4" />
          </Link>
        )}
      </SidebarFooter>
    </Sidebar>
  );
}

