import { Outlet } from "react-router-dom";
import { SidebarProvider } from "@/components/ui/sidebar";
import { AppSidebar } from "@/components/AppSidebar";
import { TopBar } from "@/components/TopBar";

export function AppLayout() {
  return (
    <SidebarProvider>
      <div className="min-h-screen flex w-full">
        <AppSidebar />
        <div className="flex-1 flex flex-col min-w-0">
          <TopBar />
          <main className="flex-1 p-8 bg-background">
            <div className="mx-auto max-w-[1200px]">
              <Outlet />
            </div>
          </main>
        </div>
      </div>
    </SidebarProvider>
  );
}

const Scan = () => (
  <div className="space-y-6">
    <h2 className="text-[28px] font-bold text-foreground">New Scan</h2>
    <p className="text-muted-foreground">Enter a URL to analyze — coming soon.</p>
  </div>
);
export default Scan;

const Reports = () => (
  <div className="space-y-6">
    <h2 className="text-[28px] font-bold text-foreground">My Reports</h2>
    <p className="text-muted-foreground">Your scan reports will appear here.</p>
  </div>
);
export default Reports;

const Pricing = () => (
  <div className="space-y-6">
    <h2 className="text-[28px] font-bold text-foreground">Pricing</h2>
    <p className="text-muted-foreground">Plans and pricing — coming soon.</p>
  </div>
);
export default Pricing;

const SettingsPage = () => (
  <div className="space-y-6">
    <h2 className="text-[28px] font-bold text-foreground">Settings</h2>
    <p className="text-muted-foreground">Account settings — coming soon.</p>
  </div>
);
export default SettingsPage;

