import {
  Lightbulb,
  MousePointerClick,
  Shield,
  Eye,
  Smartphone,
  PenLine,
  Gauge,
} from "lucide-react";
import type { CroPillarConfig, PricingTier, ScanStep } from "@/types";

// ── CRO Pillars ──────────────────────────────────────────────

export const CRO_PILLARS: CroPillarConfig[] = [
  {
    key: "value_proposition",
    label: "Value Proposition",
    icon: Lightbulb,
    description: "Can visitors understand what you offer in 5 seconds?",
  },
  {
    key: "cta_effectiveness",
    label: "CTA Effectiveness",
    icon: MousePointerClick,
    description: "Button visibility, copy, placement, and contrast",
  },
  {
    key: "trust_signals",
    label: "Trust Signals",
    icon: Shield,
    description: "Reviews, testimonials, security badges, social proof",
  },
  {
    key: "visual_hierarchy",
    label: "Visual Hierarchy",
    icon: Eye,
    description: "Eye flow, section order, whitespace, readability",
  },
  {
    key: "mobile_experience",
    label: "Mobile Experience",
    icon: Smartphone,
    description: "Responsive design, tap targets, mobile load speed",
  },
  {
    key: "content_copy",
    label: "Content & Copy",
    icon: PenLine,
    description: "Headline strength, clarity, benefit-focused writing",
  },
  {
    key: "page_performance",
    label: "Page Performance",
    icon: Gauge,
    description: "Load speed, Core Web Vitals, image optimization",
  },
];

// ── Score Thresholds ─────────────────────────────────────────

export const SCORE_THRESHOLDS = {
  poor: 40,
  average: 70,
} as const;

// ── Plan Limits ──────────────────────────────────────────────

export const PLAN_LIMITS = {
  free: 3,
  pro: 50,
  agency: 500,
} as const;

// ── Pricing Tiers ────────────────────────────────────────────

export const PRICING_TIERS: PricingTier[] = [
  {
    name: "Free",
    plan: "free",
    price_monthly: 0,
    price_annual: 0,
    subtitle: "For getting started",
    highlighted: false,
    cta_text: "Get Started Free",
    features: [
      { text: "3 page scans per month", included: true },
      { text: "Basic CRO score (7 pillars)", included: true },
      { text: "Top 3 suggestions per scan", included: true },
      { text: "AI-rewritten alternatives", included: false },
      { text: "PDF report download", included: false },
      { text: "Monthly monitoring & alerts", included: false },
      { text: "Integrations (Hotjar, GA)", included: false },
      { text: "White-label reports", included: false },
    ],
  },
  {
    name: "Pro",
    plan: "pro",
    price_monthly: 49,
    price_annual: 39,
    subtitle: "For growing businesses",
    highlighted: true,
    cta_text: "Start Pro Trial — 14 Days Free",
    features: [
      { text: "50 page scans per month", included: true },
      { text: "Full CRO score (7 pillars)", included: true },
      { text: "All suggestions unlocked", included: true },
      { text: "AI-rewritten alternatives", included: true },
      { text: "PDF report download", included: true },
      { text: "Monthly monitoring & alerts", included: true },
      { text: "Integrations (Hotjar, GA)", included: false },
      { text: "White-label reports", included: false },
    ],
  },
  {
    name: "Agency",
    plan: "agency",
    price_monthly: 199,
    price_annual: 159,
    subtitle: "For agencies & consultants",
    highlighted: false,
    cta_text: "Start Agency Trial",
    features: [
      { text: "500 page scans per month", included: true },
      { text: "Full CRO score (7 pillars)", included: true },
      { text: "All suggestions unlocked", included: true },
      { text: "AI-rewritten alternatives", included: true },
      { text: "PDF report download", included: true },
      { text: "Monthly monitoring & alerts", included: true },
      { text: "Hotjar, GA, Clarity integrations", included: true },
      { text: "White-label reports & API access", included: true },
    ],
  },
];

// ── Scan Steps ───────────────────────────────────────────────

export const SCAN_STEPS: ScanStep[] = [
