import { SCORE_THRESHOLDS } from "./constants";
import type { Severity } from "@/types";

/** Returns a Tailwind text color class based on score */
export function getScoreColor(score: number): string {
  if (score < SCORE_THRESHOLDS.poor) return "text-red-500";
  if (score < SCORE_THRESHOLDS.average) return "text-amber-500";
  return "text-green-500";
}

/** Returns a Tailwind bg color class based on score */
export function getScoreBgColor(score: number): string {
  if (score < SCORE_THRESHOLDS.poor) return "bg-red-500";
  if (score < SCORE_THRESHOLDS.average) return "bg-amber-500";
  return "bg-green-500";
}

/** Returns a light Tailwind bg for score (for card backgrounds) */
export function getScoreBgLight(score: number): string {
  if (score < SCORE_THRESHOLDS.poor) return "bg-red-50";
  if (score < SCORE_THRESHOLDS.average) return "bg-amber-50";
  return "bg-green-50";
}

/** Returns a CSS hex color for SVG strokes */
export function getScoreHex(score: number): string {
  if (score < SCORE_THRESHOLDS.poor) return "#EF4444";
  if (score < SCORE_THRESHOLDS.average) return "#F59E0B";
  return "#22C55E";
}

/** Returns a human-readable score label */
export function getScoreLabel(score: number): string {
  if (score < 25) return "Poor";
  if (score < SCORE_THRESHOLDS.poor) return "Needs Work";
  if (score < 60) return "Fair";
  if (score < SCORE_THRESHOLDS.average) return "Average";
  if (score < 85) return "Good";
  return "Excellent";
}

/** Returns Tailwind classes for severity badges */
export function getSeverityColor(severity: Severity): {
  bg: string;
  text: string;
  border: string;
} {
  switch (severity) {
    case "critical":
      return { bg: "bg-red-50", text: "text-red-700", border: "border-red-200" };
    case "warning":
      return { bg: "bg-amber-50", text: "text-amber-700", border: "border-amber-200" };
    case "info":
      return { bg: "bg-blue-50", text: "text-blue-700", border: "border-blue-200" };
    case "passed":
      return { bg: "bg-green-50", text: "text-green-700", border: "border-green-200" };
  }
}

/** Returns a severity label */
export function getSeverityLabel(severity: Severity): string {
  switch (severity) {
    case "critical": return "Critical";
    case "warning": return "Warning";
    case "info": return "Info";
    case "passed": return "Passed";
  }
}

/** Formats a score for display */
export function formatScore(score: number): string {
  return Math.round(score).toString();
}

