import { Link } from "react-router-dom";
import {
  ScanLine,
  Target,
  AlertTriangle,
  DollarSign,
  ArrowRight,
  ExternalLink,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  ResponsiveContainer,
  Cell,
} from "recharts";
import { PageHeader } from "@/components/shared/PageHeader";
import { KpiCard } from "@/components/shared/KpiCard";
import { ScoreRing } from "@/components/shared/ScoreRing";
import { UrlInput } from "@/components/shared/UrlInput";
import { PageTransition } from "@/components/shared/PageTransition";
import { getScoreColor } from "@/lib/score-utils";
import {
  MOCK_DASHBOARD_STATS,
  MOCK_SCANS,
  MOCK_SCORE_DISTRIBUTION,
} from "@/lib/mock-data";
import { cn } from "@/lib/utils";

const recentScans = MOCK_SCANS.filter((s) => s.status === "completed")
  .sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime())
  .slice(0, 5);

const stats = MOCK_DASHBOARD_STATS;

function formatDate(dateStr: string) {
  return new Date(dateStr).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

function getStatusBadge(status: string) {
  if (status === "completed") {
    return <Badge variant="outline" className="border-green-200 bg-green-50 text-green-700 text-xs">Completed</Badge>;
  }
  if (status === "analyzing") {
    return <Badge variant="outline" className="border-amber-200 bg-amber-50 text-amber-700 text-xs animate-pulse">Analyzing...</Badge>;
  }
  return <Badge variant="outline" className="text-xs">{status}</Badge>;
}

const Dashboard = () => {
  return (
    <PageTransition>
      <div className="space-y-8">
        <PageHeader
          title="Welcome back!"
          description="Here's your CRO performance overview."
        />

        {/* KPI Cards */}
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
          <KpiCard
            title="Total Scans"
            value={stats.total_scans}
            icon={ScanLine}
            trend={stats.scans_trend}
            iconBg="bg-primary/10"
            iconColor="text-primary"
          />
          <KpiCard
            title="Avg. CRO Score"
            value={stats.avg_score}
            suffix="/100"
            icon={Target}
            trend={stats.score_trend}
            iconBg="bg-amber-50"
            iconColor="text-amber-500"
            valueColor={getScoreColor(stats.avg_score)}
          />
          <KpiCard
            title="Issues Found"
            value={stats.total_issues}
            icon={AlertTriangle}
            iconBg="bg-red-50"
            iconColor="text-red-500"
          />
          <KpiCard
            title="Est. Revenue Impact"
            value={stats.estimated_revenue_impact}
            prefix="$"
            suffix="/mo"
            icon={DollarSign}
            iconBg="bg-green-50"
            iconColor="text-green-500"
          />
        </div>

        {/* Main content grid */}
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
          {/* Recent Scans Table */}
          <Card className="border-slate-200 shadow-none lg:col-span-2">
            <CardHeader className="flex flex-row items-center justify-between pb-4">
              <CardTitle className="text-base font-semibold">Recent Scans</CardTitle>
              <Button variant="ghost" size="sm" asChild className="text-primary hover:text-primary">
                <Link to="/reports">
                  View All
                  <ArrowRight className="ml-1 h-3.5 w-3.5" />
                </Link>
              </Button>
            </CardHeader>
            <CardContent className="px-0 pb-0">
              <Table>
                <TableHeader>
                  <TableRow className="bg-slate-50/50 hover:bg-slate-50/50">
                    <TableHead className="pl-6 text-xs font-medium uppercase tracking-wider text-muted-foreground">
                      Website
                    </TableHead>
                    <TableHead className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
                      Score
                    </TableHead>
                    <TableHead className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
                      Issues
                    </TableHead>
                    <TableHead className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
                      Status
                    </TableHead>
                    <TableHead className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
                      Date
                    </TableHead>
                    <TableHead className="pr-6 text-right text-xs font-medium uppercase tracking-wider text-muted-foreground">
                      Action
                    </TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {recentScans.map((scan) => (
                    <TableRow key={scan.id} className="hover:bg-slate-50/50">
                      <TableCell className="pl-6">
                        <div className="flex items-center gap-2.5">
                          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-slate-100">
                            <ExternalLink className="h-3.5 w-3.5 text-slate-400" />
                          </div>
                          <span className="max-w-[200px] truncate text-sm font-medium text-foreground">
                            {new URL(scan.url).hostname}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell>
                        <ScoreRing
                          score={scan.overall_score ?? 0}
                          size={36}
                          strokeWidth={3}
                          showLabel={false}
                        />
                      </TableCell>
                      <TableCell>
                        <span className="text-sm text-muted-foreground">
                          {scan.issues_found}
                          {scan.critical_issues > 0 && (
                            <span className="ml-1 text-red-500">({scan.critical_issues} critical)</span>
                          )}
                        </span>
                      </TableCell>
                      <TableCell>{getStatusBadge(scan.status)}</TableCell>
                      <TableCell className="text-sm text-muted-foreground">
                        {formatDate(scan.created_at)}
                      </TableCell>
                      <TableCell className="pr-6 text-right">
                        <Button variant="ghost" size="sm" asChild className="text-primary hover:text-primary">
                          <Link to={`/reports/${scan.id}`}>View</Link>
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>

          {/* Right sidebar */}
          <div className="space-y-6">
            {/* Quick Scan */}
            <Card className="border-slate-200 shadow-none">
              <CardHeader className="pb-3">
                <CardTitle className="text-base font-semibold">Quick Scan</CardTitle>
              </CardHeader>
              <CardContent>
                <UrlInput buttonText="Scan" />
                <div className="mt-3 flex flex-wrap gap-2">
                  {["~30 seconds", "7 pillars", "AI suggestions"].map((tag) => (
                    <span
                      key={tag}
                      className="inline-flex items-center rounded-full bg-slate-100 px-2.5 py-1 text-xs text-muted-foreground"
                    >
                      {tag}
                    </span>
                  ))}
                </div>
              </CardContent>
            </Card>

            {/* Score Distribution */}
            <Card className="border-slate-200 shadow-none">
              <CardHeader className="pb-3">
                <CardTitle className="text-base font-semibold">Score Distribution</CardTitle>
              </CardHeader>
              <CardContent>
                <ResponsiveContainer width="100%" height={160}>
                  <BarChart data={MOCK_SCORE_DISTRIBUTION} barCategoryGap="20%">
                    <XAxis
                      dataKey="range"
                      tick={{ fontSize: 11, fill: "#94A3B8" }}
                      axisLine={false}
                      tickLine={false}
                    />
                    <YAxis hide />
                    <Bar dataKey="count" radius={[4, 4, 0, 0]}>
                      {MOCK_SCORE_DISTRIBUTION.map((entry, index) => (
                        <Cell key={index} fill={entry.fill} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
    </PageTransition>
  );
};

export default Dashboard;

