import { getScoreColor, getScoreBgLight } from "@/lib/score-utils";
import { CRO_PILLARS } from "@/lib/constants";
import { MOCK_SCANS, MOCK_PILLAR_RESULTS } from "@/lib/mock-data";
import { cn } from "@/lib/utils";

function formatDateTime(dateStr: string) {
  return new Date(dateStr).toLocaleDateString("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

const AuditReport = () => {
  const { id } = useParams();
  const scan = MOCK_SCANS.find((s) => s.id === id) ?? MOCK_SCANS[0];
  const pillarResults = MOCK_PILLAR_RESULTS.filter((r) => r.scan_id === scan.id);

  // Sort pillars by score ascending (worst first)
  const sortedPillars = [...pillarResults].sort((a, b) => a.score - b.score);

  const totalFindings = pillarResults.reduce((sum, p) => sum + p.findings.length, 0);
  const lockedFindings = pillarResults.reduce(
    (sum, p) => sum + p.findings.filter((f) => f.is_premium).length,
    0
  );

  // Key issues for the overlay
  const criticalFindings = pillarResults
    .flatMap((p) => p.findings)
    .filter((f) => f.severity === "critical" || f.severity === "warning")
    .slice(0, 5);

  return (
    <PageTransition>
      <div className="space-y-8">
        {/* Back link */}
        <Button variant="ghost" size="sm" asChild className="text-muted-foreground -ml-2">
          <Link to="/reports">
            <ArrowLeft className="mr-1 h-3.5 w-3.5" />
            Back to Reports
          </Link>
        </Button>

        {/* Report Header */}
        <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
          <div className="space-y-1.5">
            <div className="flex items-center gap-2">
              <Globe className="h-4 w-4 text-muted-foreground" />
              <a
                href={scan.url}
                target="_blank"
                rel="noopener noreferrer"
                className="text-sm text-primary hover:underline"
              >
                {scan.url}
              </a>
            </div>
            <h2 className="text-[28px] font-bold text-foreground">Audit Report</h2>
            <div className="flex items-center gap-3 text-sm text-muted-foreground">
              <div className="flex items-center gap-1">
                <Calendar className="h-3.5 w-3.5" />
                {scan.completed_at ? formatDateTime(scan.completed_at) : "In progress"}
              </div>
              <Badge variant="outline" className="text-xs capitalize">
                {scan.page_type}
              </Badge>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" className="border-slate-200">
              <Download className="mr-1.5 h-3.5 w-3.5" />
              Download PDF
            </Button>
            <Button variant="outline" size="sm" className="border-slate-200">
              <Share2 className="mr-1.5 h-3.5 w-3.5" />
              Share
            </Button>
            <Button size="sm">
              <RefreshCw className="mr-1.5 h-3.5 w-3.5" />
              Re-scan
            </Button>
          </div>
        </div>

        {/* Score Overview */}
        <Card
          className={cn(
            "border-slate-200 shadow-none",
            scan.overall_score !== null && getScoreBgLight(scan.overall_score)
          )}
        >
          <CardContent className="p-8">
            <div className="grid grid-cols-1 items-center gap-8 md:grid-cols-3">
              {/* Giant score ring */}
              <div className="flex justify-center md:justify-start">
                <ScoreRing score={scan.overall_score ?? 0} size={200} strokeWidth={12} />
              </div>

              {/* Pillar scores */}
              <div className="space-y-3 md:col-span-2">
                <h3 className="mb-4 text-sm font-semibold uppercase tracking-wider text-muted-foreground">
                  CRO Pillar Scores
                </h3>
                {sortedPillars.map((result) => (
                  <PillarProgressBar
                    key={result.pillar}
                    pillar={result.pillar}
                    score={result.score}
                  />
                ))}
                {/* Show default bars for pillars without results */}
                {CRO_PILLARS.filter(
                  (p) => !pillarResults.some((r) => r.pillar === p.key)
                ).map((pillar) => (
                  <PillarProgressBar
                    key={pillar.key}
                    pillar={pillar.key}
                    score={0}
                  />
                ))}
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Screenshot + Key Issues */}
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-5">
          <div className="lg:col-span-3">
            <BrowserFrame url={scan.url}>
              <div className="flex h-72 items-center justify-center bg-gradient-to-br from-slate-50 via-slate-100 to-slate-50">
                <div className="text-center">
                  <div className="mx-auto mb-3 h-12 w-12 rounded-xl bg-slate-200/60" />
                  <p className="text-sm font-medium text-slate-400">Page Screenshot</p>
                  <p className="mt-1 text-xs text-slate-300">
                    Screenshot capture available in production
                  </p>
                </div>
              </div>
            </BrowserFrame>
          </div>

          <Card className="border-slate-200 shadow-none lg:col-span-2">
            <CardHeader className="pb-3">
              <CardTitle className="flex items-center gap-2 text-base font-semibold">
                <AlertCircle className="h-4 w-4 text-red-500" />
                Key Issues
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              {criticalFindings.map((finding) => (
                <div
                  key={finding.id}
                  className="flex items-start gap-3 rounded-lg border border-slate-100 p-3"
                >
                  <SeverityBadge severity={finding.severity} />
                  <span className="text-sm text-slate-700">{finding.title}</span>
                </div>
              ))}
            </CardContent>
          </Card>
        </div>

        {/* Detailed Findings Tabs */}
        <Card className="border-slate-200 shadow-none">
          <CardHeader>
            <CardTitle className="text-base font-semibold">Detailed Findings</CardTitle>
          </CardHeader>
          <CardContent>
            <Tabs defaultValue={sortedPillars[0]?.pillar ?? "value_proposition"}>
              <TabsList className="mb-6 flex w-full flex-wrap gap-1 bg-transparent h-auto p-0">
                {CRO_PILLARS.map((pillar) => {
                  const result = pillarResults.find((r) => r.pillar === pillar.key);
                  const findingCount = result?.findings.length ?? 0;
                  return (
                    <TabsTrigger
                      key={pillar.key}
                      value={pillar.key}
                      className="rounded-lg border border-transparent px-3 py-2 text-sm data-[state=active]:border-primary/20 data-[state=active]:bg-primary/5 data-[state=active]:text-primary"
                    >
                      {pillar.label}
                      {findingCount > 0 && (
                        <span className="ml-1.5 rounded-full bg-slate-100 px-1.5 py-0.5 text-xs text-slate-600">
                          {findingCount}
                        </span>
                      )}
                    </TabsTrigger>
                  );
                })}
              </TabsList>

              {CRO_PILLARS.map((pillar) => {
                const result = pillarResults.find((r) => r.pillar === pillar.key);
                return (
                  <TabsContent key={pillar.key} value={pillar.key}>
                    {result && result.findings.length > 0 ? (
                      <div className="space-y-4">
                        {/* Pillar score summary */}
                        <div className="flex items-center gap-3 rounded-lg bg-slate-50 p-4">
                          <pillar.icon className="h-5 w-5 text-muted-foreground" />
                          <div>
                            <p className="text-sm font-medium text-foreground">{pillar.label}</p>
                            <p className="text-xs text-muted-foreground">{pillar.description}</p>
                          </div>
                          <span className={cn("ml-auto text-2xl font-bold", getScoreColor(result.score))}>
                            {result.score}/100
                          </span>
                        </div>

                        {/* Findings */}
                        {result.findings.map((finding) => (
                          <FindingCard key={finding.id} finding={finding} />
                        ))}
                      </div>
                    ) : (
                      <div className="py-12 text-center text-sm text-muted-foreground">
                        No findings for this pillar yet.
                      </div>
                    )}
                  </TabsContent>
                );
              })}
            </Tabs>
          </CardContent>
        </Card>

        {/* Bottom CTA for free users */}
        {lockedFindings > 0 && (
          <Card className="border-primary/20 bg-gradient-to-r from-primary/5 to-primary/10 shadow-none">
            <CardContent className="flex flex-col items-center p-8 text-center">
              <h3 className="text-xl font-bold text-foreground">
                Unlock all suggestions + AI rewrites
              </h3>
              <p className="mt-2 text-sm text-muted-foreground">
                Get specific fixes for all {totalFindings} issues found on this page.{" "}
                <span className="font-medium text-primary">{lockedFindings} findings locked.</span>
              </p>
              <Button asChild size="lg" className="mt-5 rounded-xl px-8 font-semibold">
                <Link to="/pricing">Upgrade to Pro — $49/month</Link>
              </Button>
              <p className="mt-3 text-xs text-muted-foreground">
                Or continue with {MOCK_USER.scan_limit - MOCK_USER.scans_used} free scans remaining
              </p>
            </CardContent>
          </Card>
        )}
      </div>
    </PageTransition>
  );
};

export default AuditReport;

