import { useState } from "react";
import { Check, X, Zap } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { PageTransition } from "@/components/shared/PageTransition";
import { PRICING_TIERS } from "@/lib/constants";
import { cn } from "@/lib/utils";

const FAQ_ITEMS = [
  {
    q: "How does the free trial work?",
    a: "Start with our Pro plan free for 14 days. No credit card required. If you decide not to upgrade, you'll automatically switch to the Free plan with 3 scans per month.",
  },
  {
    q: "Can I change plans later?",
    a: "Yes! You can upgrade or downgrade your plan at any time. Changes take effect immediately. If you downgrade, you'll keep your current plan until the end of the billing period.",
  },
  {
    q: "What counts as a scan?",
    a: "One scan = one URL analyzed. Each time you submit a URL for analysis, it counts as one scan. Re-scanning the same URL counts as a new scan.",
  },
  {
    q: "Do you offer refunds?",
    a: "Yes, we offer a 30-day money-back guarantee. If you're not satisfied with ConvertScan, contact us within 30 days for a full refund.",
  },
  {
    q: "Is my data secure?",
    a: "Absolutely. All data is encrypted in transit (TLS 1.3) and at rest (AES-256). We never share your data with third parties. We're GDPR compliant and you can delete your data at any time.",
  },
];

const Pricing = () => {
  const [isAnnual, setIsAnnual] = useState(false);

  return (
    <PageTransition>
      <div className="space-y-12">
        {/* Header */}
        <div className="text-center">
          <h2 className="text-[28px] font-bold text-foreground">
            Simple, transparent pricing
          </h2>
          <p className="mt-2 text-muted-foreground">
            Start free. Upgrade when you're ready.
          </p>

          {/* Annual toggle */}
          <div className="mt-6 flex items-center justify-center gap-3">
            <Label htmlFor="billing-toggle" className={cn("text-sm", !isAnnual && "font-semibold text-foreground")}>
              Monthly
            </Label>
            <Switch
              id="billing-toggle"
              checked={isAnnual}
              onCheckedChange={setIsAnnual}
            />
            <Label htmlFor="billing-toggle" className={cn("text-sm", isAnnual && "font-semibold text-foreground")}>
              Annual
            </Label>
            {isAnnual && (
              <Badge className="bg-green-50 text-green-700 border-green-200 text-xs">
                Save 20%
              </Badge>
            )}
          </div>
        </div>

        {/* Pricing Cards */}
        <div className="mx-auto grid max-w-4xl grid-cols-1 gap-6 md:grid-cols-3">
          {PRICING_TIERS.map((tier) => {
            const price = isAnnual ? tier.price_annual : tier.price_monthly;
            return (
              <Card
                key={tier.plan}
                className={cn(
                  "relative border-slate-200 shadow-none transition-all",
                  tier.highlighted &&
                    "border-primary ring-2 ring-primary/20 scale-[1.02] shadow-lg shadow-primary/10"
                )}
              >
                {tier.highlighted && (
                  <div className="absolute -top-3 left-1/2 -translate-x-1/2">
                    <Badge className="bg-primary text-primary-foreground px-3 py-1 text-xs font-semibold">
                      <Zap className="mr-1 h-3 w-3" />
                      Most Popular
                    </Badge>
                  </div>
                )}
                <CardHeader className="text-center pb-2 pt-8">
                  <CardTitle
                    className={cn(
                      "text-lg font-semibold",
                      tier.highlighted ? "text-primary" : "text-foreground"
                    )}
                  >
                    {tier.name}
                  </CardTitle>
                  <CardDescription className="text-sm">{tier.subtitle}</CardDescription>
                </CardHeader>
                <CardContent className="text-center">
                  <div className="mb-6">
                    <span className="text-[48px] font-bold leading-none text-foreground">
                      ${price}
                    </span>
                    <span className="text-muted-foreground">/month</span>
                    {isAnnual && tier.price_monthly > 0 && (
                      <p className="mt-1 text-xs text-muted-foreground">
                        Billed annually (${price * 12}/year)
                      </p>
                    )}
                  </div>

                  <Button
                    className={cn(
                      "w-full rounded-lg",
                      tier.highlighted
                        ? "bg-primary hover:bg-primary/90"
                        : "bg-white border border-slate-200 text-foreground hover:bg-slate-50"
                    )}
                    variant={tier.highlighted ? "default" : "outline"}
                  >
                    {tier.cta_text}
                  </Button>

                  <ul className="mt-6 space-y-3 text-left">
                    {tier.features.map((feature, i) => (
                      <li key={i} className="flex items-start gap-2.5">
                        {feature.included ? (
                          <Check className="mt-0.5 h-4 w-4 shrink-0 text-green-500" />
                        ) : (
                          <X className="mt-0.5 h-4 w-4 shrink-0 text-slate-300" />
                        )}
                        <span
                          className={cn(
                            "text-sm",
                            feature.included ? "text-slate-700" : "text-slate-400"
                          )}
                        >
                          {feature.text}
                        </span>
                      </li>
                    ))}
                  </ul>
                </CardContent>
              </Card>
            );
          })}
        </div>

        {/* Trust line */}
        <p className="text-center text-xs text-muted-foreground">
          All plans include: SSL encryption &middot; GDPR compliant &middot; Cancel anytime &middot; 24-hour support
        </p>

        {/* FAQ */}
        <div className="mx-auto max-w-2xl">
          <h3 className="mb-6 text-center text-xl font-bold text-foreground">
            Frequently Asked Questions
          </h3>
          <Accordion type="single" collapsible className="w-full">
            {FAQ_ITEMS.map((item, i) => (
              <AccordionItem key={i} value={`faq-${i}`}>
                <AccordionTrigger className="text-sm font-medium text-foreground hover:text-primary">
                  {item.q}
                </AccordionTrigger>
                <AccordionContent className="text-sm text-muted-foreground leading-relaxed">
                  {item.a}
                </AccordionContent>
              </AccordionItem>
            ))}
          </Accordion>
        </div>
      </div>
    </PageTransition>
  );
};

export default Pricing;

