import { Link } from "react-router-dom";
import {
  ScanLine,
  Target,
  AlertTriangle,
  DollarSign,
  ArrowRight,
  ExternalLink,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  ResponsiveContainer,
  Cell,
} from "recharts";
import { PageHeader } from "@/components/shared/PageHeader";
import { KpiCard } from "@/components/shared/KpiCard";
import { ScoreRing } from "@/components/shared/ScoreRing";
import { UrlInput } from "@/components/shared/UrlInput";
import { PageTransition } from "@/components/shared/PageTransition";
import { getScoreColor } from "@/lib/score-utils";
import {
  MOCK_DASHBOARD_STATS,
  MOCK_SCANS,
  MOCK_SCORE_DISTRIBUTION,
} from "@/lib/mock-data";
import { cn } from "@/lib/utils";

const recentScans = MOCK_SCANS.filter((s) => s.status === "completed")
  .sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime())
  .slice(0, 5);

const stats = MOCK_DASHBOARD_STATS;

function formatDate(dateStr: string) {
  return new Date(dateStr).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

function getStatusBadge(status: string) {
  if (status === "completed") {
    return <Badge variant="outline" className="border-green-200 bg-green-50 text-green-700 text-xs">Completed</Badge>;
  }
  if (status === "analyzing") {
    return <Badge variant="outline" className="border-amber-200 bg-amber-50 text-amber-700 text-xs animate-pulse">Analyzing...</Badge>;
  }
  return <Badge variant="outline" className="text-xs">{status}</Badge>;
}

const Dashboard = () => {
  return (
    <PageTransition>
      <div className="space-y-8">
        <PageHeader
          title="Welcome back!"
          description="Here's your CRO performance overview."
        />

        {/* KPI Cards */}
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
          <KpiCard
            title="Total Scans"
            value={stats.total_scans}
            icon={ScanLine}
            trend={stats.scans_trend}
            iconBg="bg-primary/10"
            iconColor="text-primary"
          />
          <KpiCard
            title="Avg. CRO Score"
            value={stats.avg_score}
            suffix="/100"
            icon={Target}
            trend={stats.score_trend}
