  .sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime())
  .slice(0, 5);

const stats = MOCK_DASHBOARD_STATS;

function formatDate(dateStr: string) {
  return new Date(dateStr).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

function getStatusBadge(status: string) {
  if (status === "completed") {
    return <Badge variant="outline" className="border-green-200 bg-green-50 text-green-700 text-xs">Completed</Badge>;
  }
  if (status === "analyzing") {
    return <Badge variant="outline" className="border-amber-200 bg-amber-50 text-amber-700 text-xs animate-pulse">Analyzing...</Badge>;
  }
  return <Badge variant="outline" className="text-xs">{status}</Badge>;
}

