import { SCORE_THRESHOLDS } from "./constants";
import type { Severity, Effort, CroPillar, PageType, PillarResult } from "@/types";

// ── Score Colors ─────────────────────────────────────────────

export function getScoreColor(score: number): string {
  if (score < SCORE_THRESHOLDS.poor) return "text-red-500";
  if (score < SCORE_THRESHOLDS.average) return "text-amber-500";
  return "text-green-500";
}

export function getScoreBgColor(score: number): string {
  if (score < SCORE_THRESHOLDS.poor) return "bg-red-500";
  if (score < SCORE_THRESHOLDS.average) return "bg-amber-500";
  return "bg-green-500";
}

export function getScoreBgLight(score: number): string {
  if (score < SCORE_THRESHOLDS.poor) return "bg-red-50";
  if (score < SCORE_THRESHOLDS.average) return "bg-amber-50";
  return "bg-green-50";
}

export function getScoreHex(score: number): string {
  if (score < SCORE_THRESHOLDS.poor) return "#EF4444";
  if (score < SCORE_THRESHOLDS.average) return "#F59E0B";
  return "#22C55E";
}

export function getScoreLabel(score: number): string {
  if (score < 20) return "Critical";
  if (score < SCORE_THRESHOLDS.poor) return "Poor";
  if (score < 55) return "Below Average";
  if (score < SCORE_THRESHOLDS.average) return "Average";
  if (score < 85) return "Good";
  return "Excellent";
}

// ── Severity ─────────────────────────────────────────────────

export function getSeverityColor(severity: Severity): {
  bg: string;
  text: string;
  border: string;
  dot: string;
} {
  switch (severity) {
    case "critical":
      return { bg: "bg-red-50", text: "text-red-700", border: "border-red-200", dot: "bg-red-500" };
    case "warning":
      return { bg: "bg-amber-50", text: "text-amber-700", border: "border-amber-200", dot: "bg-amber-500" };
    case "info":
      return { bg: "bg-blue-50", text: "text-blue-700", border: "border-blue-200", dot: "bg-blue-500" };
    case "passed":
      return { bg: "bg-green-50", text: "text-green-700", border: "border-green-200", dot: "bg-green-500" };
  }
}

export function getSeverityLabel(severity: Severity): string {
  switch (severity) {
    case "critical": return "Critical";
    case "warning": return "Warning";
    case "info": return "Info";
    case "passed": return "Passed";
  }
}

// ── Effort ───────────────────────────────────────────────────

export function getEffortLabel(effort: Effort): string {
  switch (effort) {
    case "quick": return "Quick Win";
    case "moderate": return "Moderate";
    case "significant": return "Significant";
  }
}

export function getEffortColor(effort: Effort): string {
  switch (effort) {
    case "quick": return "text-green-600 bg-green-50 border-green-200";
    case "moderate": return "text-amber-600 bg-amber-50 border-amber-200";
    case "significant": return "text-slate-600 bg-slate-50 border-slate-200";
  }
}

// ── Weighted Scoring ─────────────────────────────────────────

/** Pillar weights vary by page type — CTA matters more on landing pages */
const PAGE_TYPE_WEIGHTS: Record<PageType, Record<CroPillar, number>> = {
  landing: {
    value_proposition: 0.20, cta_effectiveness: 0.22, trust_signals: 0.18,
    visual_hierarchy: 0.10, mobile_experience: 0.12, content_copy: 0.10, page_performance: 0.08,
  },
  product: {
    value_proposition: 0.12, cta_effectiveness: 0.18, trust_signals: 0.22,
    visual_hierarchy: 0.10, mobile_experience: 0.15, content_copy: 0.13, page_performance: 0.10,
  },
  homepage: {
    value_proposition: 0.22, cta_effectiveness: 0.15, trust_signals: 0.15,
    visual_hierarchy: 0.15, mobile_experience: 0.12, content_copy: 0.12, page_performance: 0.09,
  },
  pricing: {
    value_proposition: 0.15, cta_effectiveness: 0.20, trust_signals: 0.22,
    visual_hierarchy: 0.12, mobile_experience: 0.10, content_copy: 0.13, page_performance: 0.08,
  },
  signup: {
    value_proposition: 0.18, cta_effectiveness: 0.25, trust_signals: 0.20,
    visual_hierarchy: 0.08, mobile_experience: 0.15, content_copy: 0.08, page_performance: 0.06,
  },
  blog: {
    value_proposition: 0.10, cta_effectiveness: 0.12, trust_signals: 0.08,
    visual_hierarchy: 0.15, mobile_experience: 0.15, content_copy: 0.25, page_performance: 0.15,
  },
  other: {
    value_proposition: 0.15, cta_effectiveness: 0.15, trust_signals: 0.15,
    visual_hierarchy: 0.14, mobile_experience: 0.14, content_copy: 0.14, page_performance: 0.13,
  },
};

export function getPillarWeight(pillar: CroPillar, pageType: PageType): number {
  return PAGE_TYPE_WEIGHTS[pageType]?.[pillar] ?? 0.14;
}

export function calculateWeightedScore(results: PillarResult[], pageType: PageType): number {
  let totalWeight = 0;
  let weightedSum = 0;
  for (const r of results) {
    const w = getPillarWeight(r.pillar, pageType);
    weightedSum += r.score * w;
    totalWeight += w;
  }
  return totalWeight > 0 ? Math.round(weightedSum / totalWeight) : 0;
}

// ── Industry Benchmarks ──────────────────────────────────────

const INDUSTRY_BENCHMARKS: Record<CroPillar, number> = {
  value_proposition: 62,
  cta_effectiveness: 55,
  trust_signals: 48,
  visual_hierarchy: 67,
  mobile_experience: 58,
  content_copy: 60,
  page_performance: 72,
};

export function getIndustryBenchmark(pillar: CroPillar): number {
  return INDUSTRY_BENCHMARKS[pillar];
}

/** Returns percentile rank (0-100) — how this score compares to all scans */
export function getPercentileRank(score: number): number {
  // Simulated distribution based on CRO industry data
  if (score >= 90) return 97;
  if (score >= 80) return 88;
  if (score >= 70) return 72;
  if (score >= 60) return 55;
  if (score >= 50) return 38;
  if (score >= 40) return 22;
  if (score >= 30) return 12;
  return 5;
}

export function formatScore(score: number): string {
  return Math.round(score).toString();
}

// ── Time Helpers ─────────────────────────────────────────────

export function getTimeGreeting(): string {
  const hour = new Date().getHours();
  if (hour < 12) return "Good morning";
  if (hour < 17) return "Good afternoon";
  return "Good evening";
}

export function formatRelativeDate(dateStr: string): string {
  const now = new Date();
  const date = new Date(dateStr);
  const diffMs = now.getTime() - date.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMs / 3600000);
  const diffDays = Math.floor(diffMs / 86400000);

  if (diffMins < 1) return "Just now";
  if (diffMins < 60) return `${diffMins}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  if (diffDays < 7) return `${diffDays}d ago`;
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

