import { useState, useEffect, useCallback } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { ScanLine, Info } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Progress } from "@/components/ui/progress";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { PageHeader } from "@/components/shared/PageHeader";
import { ScanProgressTimeline } from "@/components/shared/ScanProgressTimeline";
import { BrowserFrame } from "@/components/shared/BrowserFrame";
import { PageTransition } from "@/components/shared/PageTransition";
import { CRO_PILLARS, SCAN_STEPS, PAGE_TYPES } from "@/lib/constants";
import { MOCK_USER } from "@/lib/mock-data";
import type { PageType } from "@/types";

const Scan = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [url, setUrl] = useState(searchParams.get("url") || "");
  const [pageType, setPageType] = useState<PageType>(
    (searchParams.get("type") as PageType) || "landing"
  );
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [currentStep, setCurrentStep] = useState(-1);

  const totalSteps = SCAN_STEPS.length;
  const progressPercent =
    currentStep < 0 ? 0 : Math.round(((currentStep + 1) / totalSteps) * 100);

  const startAnalysis = useCallback(() => {
    if (!url.trim()) return;
    setIsAnalyzing(true);
    setCurrentStep(0);
  }, [url]);

  // Auto-start if URL comes from query params
  useEffect(() => {
    if (searchParams.get("url") && !isAnalyzing) {
      // Don't auto-start, just prefill
    }
  }, [searchParams, isAnalyzing]);

  // Step progression
  useEffect(() => {
    if (!isAnalyzing || currentStep < 0) return;

    if (currentStep >= totalSteps) {
      // Analysis complete — navigate to report
      const timer = setTimeout(() => {
        navigate("/reports/scan_001");
      }, 800);
      return () => clearTimeout(timer);
    }

    const timer = setTimeout(() => {
      setCurrentStep((prev) => prev + 1);
    }, 1200);

    return () => clearTimeout(timer);
  }, [isAnalyzing, currentStep, totalSteps, navigate]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    startAnalysis();
  };

  // ── Analysis Progress View ──────────────────────────────────
  if (isAnalyzing) {
    return (
      <PageTransition>
        <div className="mx-auto max-w-2xl space-y-6">
          <PageHeader title="Analyzing Your Page" description="This usually takes about 30 seconds" />

          {/* Progress bar */}
          <div className="space-y-2">
            <div className="flex items-center justify-between text-sm">
              <span className="text-muted-foreground">Progress</span>
              <span className="font-medium text-foreground">{Math.min(progressPercent, 100)}%</span>
            </div>
            <Progress value={Math.min(progressPercent, 100)} className="h-2" />
          </div>

          {/* Browser frame showing the URL */}
          <BrowserFrame url={url}>
            <div className="flex h-48 items-center justify-center bg-gradient-to-br from-slate-50 to-slate-100">
              <div className="text-center">
                <ScanLine className="mx-auto mb-2 h-8 w-8 animate-spin text-primary" />
                <p className="text-sm text-muted-foreground">Scanning page...</p>
              </div>
            </div>
          </BrowserFrame>

          {/* Step timeline */}
          <Card className="border-slate-200 shadow-none">
            <CardContent className="p-6">
              <ScanProgressTimeline steps={SCAN_STEPS} currentStep={currentStep} />
            </CardContent>
          </Card>
        </div>
      </PageTransition>
    );
  }

  // ── URL Input Form View ─────────────────────────────────────
  return (
    <PageTransition>
      <div className="mx-auto max-w-2xl space-y-8">
        <div className="text-center">
          <h2 className="text-[28px] font-bold text-foreground">Analyze Your Page</h2>
          <p className="mt-2 text-muted-foreground">
            Paste any URL and get conversion-boosting suggestions in 30 seconds
          </p>
        </div>

        {/* URL Input Card */}
        <Card className="border-slate-200 shadow-none">
          <CardContent className="p-8">
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <Input
                  type="url"
                  placeholder="https://your-website.com/landing-page"
                  value={url}
                  onChange={(e) => setUrl(e.target.value)}
                  className="h-14 rounded-xl border-slate-200 bg-white px-5 text-base placeholder:text-slate-400 focus-visible:border-primary focus-visible:ring-primary/20"
                  required
                />
              </div>
              <div>
                <Select value={pageType} onValueChange={(v) => setPageType(v as PageType)}>
                  <SelectTrigger className="h-12 rounded-xl border-slate-200 bg-white">
                    <SelectValue placeholder="Select page type" />
                  </SelectTrigger>
                  <SelectContent>
                    {PAGE_TYPES.map((type) => (
                      <SelectItem key={type.value} value={type.value}>
                        {type.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <Button
                type="submit"
                className="h-14 w-full rounded-xl text-base font-semibold"
                disabled={!url.trim()}
              >
                <ScanLine className="mr-2 h-5 w-5" />
                Start Analysis
              </Button>
            </form>

            {/* Usage indicator */}
            <div className="mt-4 flex items-center justify-center gap-2">
              <Info className="h-3.5 w-3.5 text-muted-foreground" />
              <span className="text-xs text-muted-foreground">
                Free plan: {MOCK_USER.scans_used}/{MOCK_USER.scan_limit} scans used this month
                {" "}&middot;{" "}
                <span className="text-primary cursor-pointer hover:underline">Upgrade for unlimited</span>
              </span>
            </div>
          </CardContent>
        </Card>

        {/* What we analyze */}
        <div>
          <h3 className="mb-4 text-center text-sm font-semibold uppercase tracking-wider text-muted-foreground">
            What We Analyze
          </h3>
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
            {CRO_PILLARS.map((pillar) => {
              const Icon = pillar.icon;
              return (
                <Card
                  key={pillar.key}
                  className="border-slate-200 shadow-none hover:border-primary/30 transition-colors"
                >
                  <CardContent className="flex flex-col items-center p-4 text-center">
                    <div className="mb-2 flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
                      <Icon className="h-4 w-4 text-primary" />
                    </div>
                    <p className="text-xs font-medium text-foreground leading-tight">
                      {pillar.label}
                    </p>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        </div>
      </div>
    </PageTransition>
  );
};

export default Scan;

