import { useLocation, useNavigate, Link } from "react-router-dom";
import { SidebarTrigger } from "@/components/ui/sidebar";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Bell, LogOut, Settings, User, ChevronRight } from "lucide-react";
import { MOCK_USER } from "@/lib/mock-data";

const pageTitles: Record<string, string> = {
  "/dashboard": "Dashboard",
  "/scan": "New Scan",
  "/reports": "My Reports",
  "/integrations": "Integrations",
  "/settings": "Settings",
  "/pricing": "Pricing",
};

export function TopBar() {
  const location = useLocation();
  const navigate = useNavigate();
  const user = MOCK_USER;
  const initials = user.full_name.split(" ").map((n) => n[0]).join("").toUpperCase();

  // Build breadcrumb from path
  const pathSegments = location.pathname.split("/").filter(Boolean);
  const title = pageTitles[location.pathname] ?? pageTitles[`/${pathSegments[0]}`] ?? "CROBOT";
  const isDetailPage = pathSegments.length > 1;

  return (
    <header className="flex h-14 items-center justify-between border-b border-slate-200/80 bg-white px-4">
      <div className="flex items-center gap-3">
        <SidebarTrigger className="text-muted-foreground hover:text-foreground" />

        {/* Breadcrumb */}
        <div className="flex items-center gap-1.5 text-sm">
          {isDetailPage ? (
            <>
              <Link
                to={`/${pathSegments[0]}`}
                className="text-muted-foreground hover:text-foreground transition-colors"
              >
                {pageTitles[`/${pathSegments[0]}`] ?? pathSegments[0]}
              </Link>
              <ChevronRight className="h-3.5 w-3.5 text-slate-300" />
              <span className="font-medium text-foreground truncate max-w-[200px]">
                Report
              </span>
            </>
          ) : (
            <span className="font-medium text-foreground">{title}</span>
          )}
        </div>
      </div>

      <div className="flex items-center gap-2">
        {/* Notification bell */}
        <Button variant="ghost" size="sm" className="relative h-8 w-8 p-0 text-muted-foreground hover:text-foreground">
          <Bell className="h-4 w-4" />
          <span className="absolute -top-0.5 -right-0.5 flex h-3.5 w-3.5 items-center justify-center rounded-full bg-primary text-[9px] font-bold text-white">
            2
          </span>
        </Button>

        {/* User dropdown */}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <button className="flex items-center gap-2 rounded-lg px-1.5 py-1 hover:bg-slate-100 transition-colors">
              <Avatar className="h-7 w-7">
                <AvatarFallback className="bg-primary/10 text-[10px] font-semibold text-primary">
                  {initials}
                </AvatarFallback>
              </Avatar>
              <span className="hidden text-sm font-medium text-foreground sm:inline">
                {user.full_name.split(" ")[0]}
              </span>
            </button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-48">
            <div className="px-2 py-1.5">
              <p className="text-sm font-medium text-foreground">{user.full_name}</p>
              <p className="text-xs text-muted-foreground">{user.email}</p>
            </div>
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={() => navigate("/settings")}>
              <User className="mr-2 h-3.5 w-3.5" />
              Profile
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => navigate("/settings")}>
              <Settings className="mr-2 h-3.5 w-3.5" />
              Settings
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={() => navigate("/login")} className="text-red-600">
              <LogOut className="mr-2 h-3.5 w-3.5" />
              Log out
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </header>
  );
}

