import { useState } from "react";
import { ChevronDown, Sparkles, Zap, TrendingUp, Copy, Check } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { SeverityBadge } from "./SeverityBadge";
import { PremiumLock } from "./PremiumLock";
import { cn } from "@/lib/utils";
import { getEffortLabel, getEffortColor } from "@/lib/score-utils";
import type { Finding } from "@/types";

function CopyInline({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  const handleCopy = async () => {
    try { await navigator.clipboard.writeText(text); } catch { /* fallback */ }
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };
  return (
    <button
      onClick={handleCopy}
      className={cn(
        "inline-flex items-center gap-1 rounded-md px-2 py-0.5 text-[10px] font-medium border transition-all",
        copied
          ? "bg-green-50 text-green-600 border-green-200"
          : "bg-white text-slate-500 border-slate-200 hover:bg-slate-50 hover:text-slate-700"
      )}
    >
      {copied ? <><Check className="h-2.5 w-2.5" />Copied</> : <><Copy className="h-2.5 w-2.5" />Copy</>}
    </button>
  );
}

interface FindingCardProps {
  finding: Finding;
  className?: string;
}

export function FindingCard({ finding, className }: FindingCardProps) {
  const [expanded, setExpanded] = useState(!finding.is_premium);

  const borderColor = {
    critical: "border-l-red-500",
    warning: "border-l-amber-500",
    info: "border-l-blue-500",
    passed: "border-l-green-500",
  }[finding.severity];

  const content = (
    <Card
      className={cn(
        "border-l-4 border-slate-200 shadow-none transition-shadow hover:shadow-sm",
        borderColor,
        className
      )}
    >
      <CardContent className="p-5">
        {/* Header */}
        <div className="flex items-start justify-between gap-3">
          <div className="flex flex-wrap items-center gap-2">
            <SeverityBadge severity={finding.severity} />
            <h4 className="text-sm font-semibold text-foreground">{finding.title}</h4>
          </div>
          <div className="flex items-center gap-1.5 shrink-0">
            {/* Effort badge */}
            <span className={cn(
              "hidden sm:inline-flex items-center gap-0.5 rounded-full border px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide",
              getEffortColor(finding.effort)
            )}>
              <Zap className="h-2.5 w-2.5" />
              {getEffortLabel(finding.effort)}
            </span>
            {/* Lift badge */}
            {finding.estimated_lift && finding.estimated_lift !== "0%" && (
              <span className="hidden sm:inline-flex items-center gap-0.5 rounded-full border border-violet-200 bg-violet-50 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-violet-600">
                <TrendingUp className="h-2.5 w-2.5" />
                {finding.estimated_lift}
              </span>
            )}
            <button
              onClick={() => setExpanded(!expanded)}
              className="rounded-md p-1 hover:bg-slate-100 transition-colors"
            >
              <ChevronDown className={cn(
                "h-4 w-4 text-muted-foreground transition-transform duration-200",
                expanded && "rotate-180"
              )} />
            </button>
          </div>
        </div>

        {/* Mobile effort/lift badges */}
        <div className="mt-2 flex flex-wrap gap-1.5 sm:hidden">
          <span className={cn(
            "inline-flex items-center gap-0.5 rounded-full border px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide",
            getEffortColor(finding.effort)
          )}>
            <Zap className="h-2.5 w-2.5" />
            {getEffortLabel(finding.effort)}
          </span>
          {finding.estimated_lift && finding.estimated_lift !== "0%" && (
            <span className="inline-flex items-center gap-0.5 rounded-full border border-violet-200 bg-violet-50 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-violet-600">
              <TrendingUp className="h-2.5 w-2.5" />
              {finding.estimated_lift}
            </span>
          )}
        </div>

        {expanded && (
          <div className="mt-4 space-y-4 animate-fade-in">
            {/* Current state */}
            <div>
              <p className="mb-1.5 text-[11px] font-semibold uppercase tracking-widest text-muted-foreground">
                What we found
              </p>
              <div className="rounded-lg bg-slate-50 p-3.5 text-sm text-slate-600 leading-relaxed">
                {finding.current_state}
              </div>
            </div>

            {/* Recommendation */}
            <div>
              <p className="mb-1.5 text-[11px] font-semibold uppercase tracking-widest text-muted-foreground">
                How to fix it
              </p>
              <p className="text-sm text-slate-700 leading-relaxed">
                {finding.recommendation}
              </p>
            </div>

            {/* AI Suggestion */}
            {finding.ai_suggestion && (
              <div className="rounded-lg border border-primary/20 bg-primary/[0.03] p-3.5">
                <div className="mb-1.5 flex items-center justify-between">
                  <div className="flex items-center gap-1.5">
                    <Sparkles className="h-3.5 w-3.5 text-primary" />
                    <p className="text-[11px] font-semibold uppercase tracking-widest text-primary">AI Suggestion</p>
                  </div>
                  <CopyInline text={finding.ai_suggestion} />
                </div>
                <p className="text-sm text-slate-700 leading-relaxed whitespace-pre-line">
                  {finding.ai_suggestion}
                </p>
              </div>
            )}

            {/* Meta: category + effort on mobile */}
            <div className="flex items-center gap-3 text-[11px] text-muted-foreground">
              <span>Category: <span className="font-medium text-foreground">{finding.category}</span></span>
              <span>&middot;</span>
              <span>Effort: <span className="font-medium text-foreground">{getEffortLabel(finding.effort)}</span></span>
              {finding.estimated_lift && finding.estimated_lift !== "0%" && (
                <>
                  <span>&middot;</span>
                  <span>Expected lift: <span className="font-medium text-foreground">{finding.estimated_lift}</span></span>
                </>
              )}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );

  if (finding.is_premium) {
    return <PremiumLock>{content}</PremiumLock>;
  }

  return content;
}

