          <p className="mt-4 text-center text-xs text-muted-foreground">
            By signing up, you agree to our{" "}
            <a href="#" className="text-primary hover:underline">Terms</a> and{" "}
            <a href="#" className="text-primary hover:underline">Privacy Policy</a>.
          </p>

          <p className="mt-4 text-center text-sm text-muted-foreground">
            Already have an account?{" "}
            <Link to="/login" className="font-medium text-primary hover:underline">
              Log in
            </Link>
          </p>
        </div>
      </div>

      {/* Right — Testimonial panel */}
      <div className="hidden w-[45%] bg-[hsl(222,47%,11.2%)] p-12 lg:flex lg:flex-col lg:justify-center">
        <div className="mx-auto max-w-md">
          <div className="flex gap-0.5 mb-6">
            {Array.from({ length: 5 }).map((_, i) => (
              <Star key={i} className="h-5 w-5 fill-amber-400 text-amber-400" />
            ))}
          </div>
          <blockquote className="text-xl font-medium leading-relaxed text-white">
            "We replaced our $5K/month CRO agency with CROBOT. The AI suggestions are more specific and actionable than anything we got from consultants."
          </blockquote>
          <div className="mt-6 flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-full bg-white/10">
              <span className="text-sm font-bold text-white">MR</span>
            </div>
            <div>
              <p className="text-sm font-medium text-white">Mike R.</p>
              <p className="text-sm text-slate-400">Founder at ShopMetrics</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

